function renderStringList(title: string, values: string[], maxItems: number, omittedLabel: string): string[] {
  const lines = [`${title}:`];
  const visible = values.slice(0, maxItems);
  if (visible.length === 0) {
    lines.push("- none");
  } else {
    for (const value of visible) lines.push(`- ${truncateText(value)}`);
  }
  const omitted = values.length - visible.length;
  if (omitted > 0) lines.push(`- Additional ${omittedLabel} omitted: ${omitted}`);
  return lines;
}

async function continuityInitDefault(args: string[]): Promise<void> {
  const flags = parseFlags(args);
  const paths = resolveWorkspace({
    cwd: flags.cwd,
    stateRoot: flags["state-root"],
  });
  await mkdir(dirname(paths.currentPath), { recursive: true });
  const frame = await initWorkspace(paths, defaultFrameInput());
  process.stdout.write(`${renderContinuityFrame(frame)}\n`);
}

